-- The schema 0.8.0 left: every migration up to 69, folded into one file.
--
-- Generated by `scripts/squash-migrations.ts` on 2026-10-26 from the chain it replaces — `068_baseline.sql`, itself
-- 032 to 068 folded, and 0.8.0's `069_missions_automations.sql` — and verified against it: applying this file produces
-- the same `sqlite_master` as applying the chain. The 068 half was compared with a live box at 0.7.28 when it was
-- folded, the same but for one comment in `exec_grants` (`apps/engine/tests/contracts/baseline-schema.test.ts`). A
-- database at 69 holds the chain's fingerprint, which `apps/engine/src/db/migrations.ts` states for this file.
--
-- **This file is applied and never edited.** It is schema version 69, so a database already at 69
-- needs nothing; the next change is `070_*.sql`.

CREATE TABLE approvals (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  gateway TEXT NOT NULL,
  tool TEXT NOT NULL,
  params TEXT NOT NULL,                           -- JSON
  status TEXT NOT NULL DEFAULT 'pending',         -- pending | approved | denied | expired
  requested_at INTEGER NOT NULL,
  resolved_at INTEGER,
  resolved_by TEXT,                               -- sender id who answered
  timeout_ms INTEGER NOT NULL DEFAULT 300000
, decision TEXT, grantable INTEGER NOT NULL DEFAULT 0, reason TEXT, preview_json TEXT, auto_coverable INTEGER);

CREATE TABLE audit_log (
  id TEXT PRIMARY KEY,
  timestamp INTEGER NOT NULL,
  agent_id TEXT,
  actor TEXT,                                     -- user id, 'system', or 'cron'
  action TEXT NOT NULL,                           -- tool_exec | approval | config_change | login | ...
  details TEXT,                                   -- JSON
  gateway TEXT,
  chat_id TEXT
, turn_id TEXT);

CREATE TABLE auto_approve (
  gateway_id TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  enabled_at INTEGER NOT NULL,
  -- Who switched it on. The same person in practice, but an audit trail that cannot name an actor is
  -- not one, and this is a row that turns a gate off.
  enabled_by TEXT NOT NULL,
  PRIMARY KEY (gateway_id, sender_id)
);

CREATE TABLE chat_attachments (
  -- Short and stable, derived from the message id — see `attachmentRef`. It is what the model types,
  -- so it is deliberately not a UUID.
  ref TEXT PRIMARY KEY,
  -- Platform. Half of the room key.
  gateway TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  -- The connection that saw it first, for a later fetch. Not part of any lookup.
  gateway_id TEXT NOT NULL,
  name TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  kind TEXT NOT NULL,                     -- image | audio | video | document
  size INTEGER,
  -- A durable copy, when one exists. NULL means nothing has materialised it yet.
  local_path TEXT,
  -- The platform reference, as JSON, so a read can fetch bytes the first time it is asked for them.
  handle TEXT,
  -- Who put it there, phrased for the prompt: a person's display name, or the agent's id.
  sender_name TEXT,
  from_agent TEXT,
  at INTEGER NOT NULL
);

CREATE TABLE chat_events (
  id TEXT PRIMARY KEY,
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,

  -- 'agents' | 'ui' — see above. Not a boolean, because a third audience is easy to imagine
  -- (operator-only, hidden from a viewer account) and widening a text enum costs nothing.
  audience TEXT NOT NULL,

  -- What kind of thing happened, for the icon and the wording: joined | left | topic | moved |
  -- dropped | ambiguous | hop_budget | restart | note. Stored rather than derived from the text,
  -- because deriving it is what `SystemNote` in the dashboard has to do today — it matches the
  -- daemon's exact sentences with regexes, and a heading that guesses wrong lies about an outcome.
  kind TEXT NOT NULL,

  -- The sentence, already written for a reader. Composed at write time so a client (or a prompt)
  -- never has to know how to phrase an event it does not recognise.
  text TEXT NOT NULL,

  -- The agent this is *about*, when it is about one. NULL means room-wide, which is the common case.
  -- Never the writer: everything here is written by the daemon.
  agent_id TEXT,

  -- Who caused it: a dashboard account, a platform sender id, 'cron', or NULL for the daemon itself.
  actor TEXT,

  -- JSON, for anything a client may want that the sentence does not carry — the dropped message's
  -- id, the candidates in an ambiguous route. Never read by the prompt.
  details TEXT,

  at INTEGER NOT NULL
);

CREATE TABLE chat_members (
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  -- The dashboard account that added them, for the room's event log. NULL when the daemon did.
  added_by TEXT,
  added_at INTEGER NOT NULL,
  PRIMARY KEY (gateway_id, chat_id, agent_id)
);

CREATE TABLE chat_messages (
  -- The envelope's own id, so a turn's `message_id` joins straight to it and a message delivered
  -- twice by a platform cannot be recorded twice.
  id TEXT PRIMARY KEY,
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,

  sender_id TEXT NOT NULL,
  -- What to draw above the bubble in a room with more than one person in it. Nullable because a
  -- platform does not always say.
  sender_name TEXT,

  text TEXT NOT NULL,
  -- JSON: the attachments the message carried, as metadata. The bytes live in the agent's store.
  attachments TEXT,

  at INTEGER NOT NULL
);

CREATE TABLE chat_rooms (
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  -- NULL means "no name given" and the client shows the member list. Not defaulted to that string
  -- here, because a name derived at write time stops being right the moment a member is added.
  title TEXT,
  created_by TEXT,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (gateway_id, chat_id)
);

CREATE TABLE cron_jobs (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  schedule TEXT NOT NULL,                         -- JSON: CronSchedule
  payload TEXT NOT NULL,                          -- JSON: CronPayload
  delivery TEXT,                                  -- JSON: CronDelivery
  created_at INTEGER NOT NULL,
  last_run_at INTEGER,
  next_run_at INTEGER,
  run_count INTEGER NOT NULL DEFAULT 0,
  fail_count INTEGER NOT NULL DEFAULT 0
, target_gateway_id TEXT NOT NULL DEFAULT '', target_chat_id TEXT NOT NULL DEFAULT '', session TEXT NOT NULL DEFAULT 'chat', keep_after_run INTEGER NOT NULL DEFAULT 0, created_by TEXT NOT NULL DEFAULT 'system', fail_streak INTEGER NOT NULL DEFAULT 0, disabled_reason TEXT, webhook_token TEXT, reach_test TEXT, proposal TEXT, turned_on_by TEXT, allowed TEXT);

CREATE TABLE "cron_runs" (
  id TEXT PRIMARY KEY,
  -- No longer a foreign key, deliberately. The run is a record of something that happened; the job
  -- is a thing that may since have been deleted, edited or renamed. Tying the first's lifetime to
  -- the second's is what caused this.
  job_id TEXT NOT NULL,
  -- The name as it was when the run started, not as it is now. A job renamed between two runs
  -- should read as two different names in the history, because that is what happened.
  job_name TEXT,
  started_at INTEGER NOT NULL,
  finished_at INTEGER,
  status TEXT NOT NULL,                           -- success | error | skipped
  result TEXT
, held TEXT);

CREATE TABLE "events" (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  at INTEGER NOT NULL,
  turn_id TEXT,
  agent_id TEXT,
  gateway_id TEXT,
  chat_id TEXT,
  kind TEXT NOT NULL,
  data TEXT NOT NULL
);

CREATE TABLE exec_grants (
  -- Identity of the command, from execGrantKey(): version + sha256 over agent, cwd, argv and
  -- (when the command executes a file) that file's digest. NOT a primary key on its own — a
  -- revoked grant is kept for the audit trail, so the same key can legitimately appear twice.
  grant_key TEXT NOT NULL,
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,

  -- Display and forensics only. Never matched against: matching on text rather than the key is
  -- how "allow always" quietly starts covering commands nobody approved.
  command_text TEXT NOT NULL,
  argv TEXT NOT NULL,                             -- JSON array, as executed
  cwd TEXT NOT NULL,
  file_sha256 TEXT,                               -- set when an executed file operand was bound

  -- Who and what created it. `approval_id` links back to the moment it was granted so
  -- `nouride grants list` can show the chat it came from.
  created_at INTEGER NOT NULL,
  created_by TEXT NOT NULL,                       -- sender id who answered allow-always
  approval_id TEXT,
  -- The policy in force when the grant was made, as a JSON snapshot. Not part of the key: an
  -- operator adding one allowlist entry must not invalidate every grant they ever made. Kept so
  -- a surprising grant can be explained later ("this was granted while mode was full").
  policy_snapshot TEXT NOT NULL,

  revoked_at INTEGER,
  revoked_by TEXT,
  -- Usage counters, so `nouride grants list` can show what is actually load-bearing and what was
  -- granted once and never used again.
  last_used_at INTEGER,
  use_count INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE inbox (
  id TEXT PRIMARY KEY,                          -- <gatewayId>:<chatId>:<platform message id>
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  received_at INTEGER NOT NULL,
  sent_at INTEGER NOT NULL,                     -- the platform's own timestamp
  status TEXT NOT NULL CHECK (status IN ('queued', 'placed', 'done', 'unanswered')),
  reason TEXT,                                  -- why unanswered: stale, refused, dropped, interrupted, failed
  envelope TEXT NOT NULL,                       -- what it takes to queue it again, as JSON
  settled_at INTEGER
);

CREATE TABLE jobs (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  -- Where the wake-up goes when it ends. The conversation that started the job is the one that cares
  -- about it, and it is the same (gateway, chat) pair `sessions` is keyed by.
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,

  command TEXT NOT NULL,
  cwd TEXT NOT NULL,
  status TEXT NOT NULL,                    -- running | succeeded | failed | killed | interrupted
  -- Of this daemon's run only. A pid from a previous run belongs to nothing, or worse to something
  -- unrelated that has since reused the number — which is why `kill` checks for a live handle first.
  pid INTEGER,
  exit_code INTEGER,
  -- Output lives in a file, not a column. A build log is megabytes, and a file is something the agent
  -- can `read` with an offset like any other.
  log_path TEXT NOT NULL,

  started_at INTEGER NOT NULL,
  ended_at INTEGER
, on_complete TEXT, woke_at INTEGER, kind TEXT NOT NULL DEFAULT 'command', brief TEXT, report TEXT, turn_id TEXT, sender_id TEXT);

CREATE TABLE llm_usage (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  session_id TEXT,
  model TEXT NOT NULL,
  provider TEXT NOT NULL,
  input_tokens INTEGER NOT NULL,
  output_tokens INTEGER NOT NULL,
  estimated_cost_usd REAL,
  timestamp INTEGER NOT NULL
, cached_input_tokens INTEGER, cache_creation_input_tokens INTEGER, turn_id TEXT, latency_ms INTEGER, attempts INTEGER, upstream_provider TEXT, upstream_model TEXT, upstream_attempts INTEGER, purpose TEXT, basis TEXT, estimated INTEGER, duration_ms INTEGER, stop_reason TEXT);

CREATE TABLE log_entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts INTEGER NOT NULL,
  -- debug | info | warn | error. Stored as written rather than as a number: a level read back as
  -- `2` is a level somebody has to look up, and the whole point of this table is being readable.
  level TEXT NOT NULL,
  -- `gateway.telegram:bot`, `pipeline`, `tools.mcp`, `daemon` — the fastest filter there is.
  component TEXT NOT NULL,
  message TEXT NOT NULL,
  -- The structured tail of the line, as JSON. Null when there was none.
  data TEXT,
  -- Lifted out of `data` because they are what somebody filters by when a single agent or a single
  -- conversation is the thing behaving badly.
  agent_id TEXT,
  chat_id TEXT
);

CREATE TABLE mcp_oauth (
  agent_id TEXT NOT NULL,
  -- The server's name in the agent's `[[mcp_servers]]`.
  server TEXT NOT NULL,
  -- What discovery found — the resource, the endpoints, the scope asked for. JSON, `OAuthDiscovery` in `@nouride/mcp`.
  discovery TEXT NOT NULL,
  client_id TEXT NOT NULL,
  -- How the token endpoint is shown the client's secret, as the registration said; null for a public client.
  token_method TEXT,
  -- When the access token stops working, in ms; null when the server did not say.
  expires_at INTEGER,
  scope TEXT,
  -- Who logged it in — a dashboard account's name, or `cli` — and when.
  logged_in_by TEXT NOT NULL,
  logged_in_at INTEGER NOT NULL,
  PRIMARY KEY (agent_id, server)
) WITHOUT ROWID;

CREATE TABLE mcp_tokens (
  id TEXT PRIMARY KEY,
  token_hash TEXT NOT NULL UNIQUE,
  person TEXT NOT NULL,
  agents TEXT NOT NULL,                           -- comma-separated agent ids
  scopes TEXT NOT NULL,                           -- space-separated: memory, memory:write, personas
  label TEXT NOT NULL,                            -- the client, as its notes are sourced: zed, claude_code, …
  created_at INTEGER NOT NULL,
  last_used_at INTEGER,
  revoked_at INTEGER
, expires_at INTEGER);

CREATE TABLE memory_attempts (
  episode_id TEXT PRIMARY KEY,
  attempts INTEGER NOT NULL,
  last_error TEXT,
  updated_at INTEGER NOT NULL
);

CREATE TABLE memory_changes (
  id TEXT PRIMARY KEY,
  at INTEGER NOT NULL,
  subject TEXT NOT NULL,          -- a person key, or `shared`
  change TEXT NOT NULL,           -- added | updated | removed | merged
  text TEXT NOT NULL,             -- the fact as it now reads, or as it read when removed
  previous TEXT,                  -- what it said before: an update's old text, a merge's facts
  source TEXT,                    -- the conversation it came from, when there is one
  cause TEXT NOT NULL             -- pass | consolidation | agent | approval
, secondhand INTEGER NOT NULL DEFAULT 0);

CREATE TABLE memory_episode_agents (
  episode_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  PRIMARY KEY (episode_id, agent_id)
);

CREATE TABLE memory_episode_people (
  episode_id TEXT NOT NULL,
  person TEXT NOT NULL,
  role TEXT NOT NULL,
  PRIMARY KEY (episode_id, person, role)
);

CREATE TABLE memory_episode_related (
  episode_id TEXT NOT NULL,
  related_id TEXT NOT NULL,
  PRIMARY KEY (episode_id, related_id)
);

CREATE TABLE memory_episode_tags (
  episode_id TEXT NOT NULL,
  tag TEXT NOT NULL,
  PRIMARY KEY (episode_id, tag)
);

CREATE TABLE memory_episodes (
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL,                           -- raw | summarized | compacted
  kind TEXT NOT NULL,                             -- dm | group | archive
  chat TEXT NOT NULL,                             -- <gatewayId>:<chatId>
  day TEXT NOT NULL,                              -- YYYY-MM-DD, daemon time zone
  week TEXT NOT NULL,                             -- ISO week, 2026-W39
  month TEXT NOT NULL,                            -- YYYY-MM
  started_at INTEGER NOT NULL,
  ended_at INTEGER NOT NULL,
  importance INTEGER,
  summary TEXT
, preview TEXT);

CREATE TABLE memory_facts (
  id TEXT PRIMARY KEY,
  subject TEXT NOT NULL,                          -- a person key, or 'shared'
  position INTEGER NOT NULL,                      -- its place in the file: facts are numbered in file order
  section TEXT NOT NULL,
  text TEXT NOT NULL,
  source TEXT,                                    -- the episode it came from
  readers TEXT,                                   -- ',gading,mira,' — null for a line a person wrote
  readers_chat TEXT                               -- the group chat it was said in
);

CREATE TABLE memory_files (
  path TEXT PRIMARY KEY,
  mtime_ms INTEGER NOT NULL,
  size INTEGER NOT NULL
);

CREATE VIRTUAL TABLE memory_fts USING fts5(
  summary,                                       -- weight 2: what the episode is about
  tags,
  body,                                          -- the transcript while kept; a fact's section and text
  roots,                                         -- Indonesian roots of every word above, from `stemmer/`
  content = '',
  contentless_delete = 1,
  tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TABLE memory_fts_items (
  id INTEGER PRIMARY KEY,
  item TEXT NOT NULL UNIQUE                      -- an episode id, or `fact:<subject>:<hash>`
);

CREATE TABLE memory_groups (
  chat TEXT PRIMARY KEY,
  slug TEXT NOT NULL
);

CREATE TABLE memory_pass_runs (
  id TEXT PRIMARY KEY,
  started_at INTEGER NOT NULL,
  day TEXT NOT NULL,              -- YYYY-MM-DD in the daemon's time zone
  scheduled INTEGER NOT NULL,     -- 1 for the nightly run, 0 for one asked for by hand
  finished_at INTEGER,
  report TEXT                     -- the run's report, as JSON, once it finished
);

CREATE TABLE memory_tag_aliases (
  alias TEXT PRIMARY KEY,
  tag TEXT NOT NULL
);

CREATE TABLE "memory_vectors" (
  item TEXT NOT NULL,                            -- an episode id, or `fact:<subject>:<hash>`
  model TEXT NOT NULL,                           -- `provider/model@dimensions` — `vectorKey` in `semantic.ts`
  dims INTEGER NOT NULL,
  vector BLOB NOT NULL,                          -- the unit vector scaled to int8: `dims` bytes
  text_hash TEXT NOT NULL DEFAULT '',            -- what it was made from, so a rewritten summary is embedded again
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (item, model)
);

CREATE TABLE missions (
  id TEXT PRIMARY KEY,                       -- msn_<hex>
  agent_id TEXT NOT NULL,
  -- Who it runs as: the sender who started it, on `gateway_id` — their approval level and their People entry apply.
  started_by TEXT NOT NULL,
  -- The agent that started it on that person's behalf, when an agent did.
  by_agent TEXT,
  -- Where it reports: the chat it began in.
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,

  goal TEXT NOT NULL,
  checks TEXT NOT NULL DEFAULT '[]',         -- JSON: the commands the daemon runs when the agent says it is done
  review TEXT,                               -- the reviewer's criteria in words; NULL = the goal itself
  review_on INTEGER NOT NULL DEFAULT 1,      -- 0 = started with review = false
  accept INTEGER NOT NULL DEFAULT 0,         -- a person accepts after the checks pass

  status TEXT NOT NULL,                      -- queued | running | waiting | checking | done | failed | stopped
  wait_kind TEXT,                            -- approval | input | stuck | unknown_outcome | limit | accept
  reason TEXT,                               -- what it waits for, or why it ended
  report TEXT,                               -- the agent's report at the end
  files TEXT NOT NULL DEFAULT '[]',          -- JSON: the result files `done` named, inside its folder
  last_check TEXT,                           -- the failed check's output, clipped, for the next turn's page
  answers TEXT NOT NULL DEFAULT '[]',        -- JSON: the last questions it asked and their answers

  workdir TEXT NOT NULL,                     -- where it works and its checks run
  parent_id TEXT,                            -- a mission started inside another one: one level
  untrusted INTEGER NOT NULL DEFAULT 0,      -- started after its turn read outside content

  limit_hours REAL NOT NULL,
  limit_turns INTEGER NOT NULL,
  limit_tokens INTEGER NOT NULL,
  turns_used INTEGER NOT NULL DEFAULT 0,
  tokens_used INTEGER NOT NULL DEFAULT 0,    -- input + output of its turns, its helpers' and the reviewer's
  resumes INTEGER NOT NULL DEFAULT 0,        -- continues after restarts with no step finished in between
  -- Time spent waiting on a person, left out of `limit_hours`; `waiting_since` is set while it waits on one.
  waited_ms INTEGER NOT NULL DEFAULT 0,
  waiting_since INTEGER,

  -- What it has already said, so each is said once: 80% of a limit, the follow-up on a wait, the progress line, the
  -- stall nudge.
  warned_at INTEGER,
  followed_up_at INTEGER,
  progress_at INTEGER,
  progress_done INTEGER NOT NULL DEFAULT 0,
  nudged_at INTEGER,

  created_at INTEGER NOT NULL,
  started_at INTEGER,
  updated_at INTEGER NOT NULL,
  ended_at INTEGER
, job_id TEXT, request TEXT, reviewed INTEGER NOT NULL DEFAULT 0);

CREATE TABLE room_mention (
  platform TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  require_mention INTEGER NOT NULL CHECK (require_mention IN (0, 1)),
  set_by TEXT NOT NULL,
  set_at INTEGER NOT NULL,
  PRIMARY KEY (platform, chat_id)
);

CREATE TABLE room_names (
  platform TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  platform_title TEXT,
  chosen_title TEXT,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (platform, chat_id)
);

CREATE TABLE rsi_tool_seen (
  agent_id TEXT NOT NULL,
  tool_name TEXT NOT NULL,
  first_seen_at INTEGER NOT NULL,
  PRIMARY KEY (agent_id, tool_name)
) WITHOUT ROWID;

CREATE TABLE sender_access (
  gateway_id TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  -- Display only, and *untrusted*: it is whatever the platform reports as their name. Never
  -- matched against, so a person named "admin" gains nothing by it.
  sender_name TEXT,

  status TEXT NOT NULL,                        -- pending | approved | denied
  -- Short pair code, shown to the sender and typed by the operator. Cleared on resolution so a
  -- code cannot be replayed to approve a later request.
  code TEXT,
  -- Where they wrote from, so the approval can be delivered back to that conversation.
  chat_id TEXT,

  requested_at INTEGER NOT NULL,
  -- When the pair code stops working. A stale code left valid forever is a standing invitation.
  expires_at INTEGER,
  resolved_at INTEGER,
  resolved_by TEXT,
  -- Last time we told this sender they were not authorized. Rate limits that reply so an unknown
  -- sender cannot use the daemon to spam a chat, or flood the operator with pair requests.
  last_notified_at INTEGER,

  PRIMARY KEY (gateway_id, sender_id)
);

CREATE TABLE session_messages (
  session_id TEXT NOT NULL,                       -- sessions.id
  seq INTEGER NOT NULL,                           -- the order the model sees them in; not renumbered when the head goes
  hash TEXT,                                      -- of `message`, as the store writes it; NULL for the rows moved here
  message TEXT NOT NULL,                          -- one message, as JSON
  PRIMARY KEY (session_id, seq)
);

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  gateway TEXT NOT NULL,
  context_token_count INTEGER NOT NULL DEFAULT 0,
  session_type TEXT NOT NULL DEFAULT 'main',      -- main | subagent | cron | thread
  status TEXT NOT NULL DEFAULT 'active',          -- active | paused | expired
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL, started_at INTEGER NOT NULL DEFAULT 0,
  UNIQUE(agent_id, chat_id, gateway)
);

CREATE TABLE skill_candidates (
  name TEXT PRIMARY KEY,
  description TEXT NOT NULL,
  why TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  -- The conversation it was seen in: the same one again is not the work recurring.
  session_id TEXT NOT NULL,
  first_seen_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL
);

CREATE TABLE skill_drafts (
  id TEXT PRIMARY KEY,
  created_at INTEGER NOT NULL,

  -- Who drafted it, and where the work happened. The chat is how a decision made in the dashboard
  -- can be reported back into the conversation that produced the draft, and the other way round.
  agent_id TEXT NOT NULL,
  gateway_id TEXT,
  chat_id TEXT,
  session_id TEXT,

  -- Why the reflection pass ran at all: error_recovery | user_request | first_integration.
  -- Kept so the drafts view can say "this came from two failed deploys", which is most of what an
  -- operator needs to judge whether the skill is worth having.
  trigger_kind TEXT NOT NULL,
  trigger_reason TEXT NOT NULL,

  -- The proposed skill, in the pieces `SKILL.md` is assembled from rather than as one blob. The
  -- dashboard edits these fields individually before approving, and reassembling a blob to change a
  -- description is how frontmatter gets corrupted.
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  requires TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL,

  -- What the synthesis pass read, already scrubbed of anything that looked like a credential. This
  -- is the Origin Trajectory Inspector (§3.4): approving a procedure you cannot trace back to the
  -- turn that produced it is approving a model's word for it.
  transcript TEXT,
  -- Which model wrote it, so a run of bad drafts can be blamed on the right thing.
  model TEXT,

  status TEXT NOT NULL DEFAULT 'pending',  -- pending | approved | denied
  decided_at INTEGER,
  decided_by TEXT,
  -- Where the SKILL.md landed, set on approval. The audit trail's answer to "which file is this now".
  published_path TEXT
, target TEXT, files TEXT, needs_tools TEXT, carries TEXT, retire TEXT);

CREATE TABLE skill_reads (
  path TEXT PRIMARY KEY,
  -- Since when reads of it have been kept: its first read, or, for a path first asked about, the oldest audit row
  -- searched for one. "Not read since then" is true; "never read" would not be.
  watched_since INTEGER NOT NULL,
  -- The last read; NULL when there has been none since `watched_since`.
  read_at INTEGER
);

CREATE TABLE skill_reviews (
  ran_at INTEGER PRIMARY KEY,
  report TEXT NOT NULL
);

CREATE TABLE tool_grants (
  id           TEXT PRIMARY KEY,
  grant_key    TEXT NOT NULL,
  agent_id     TEXT NOT NULL,
  tool         TEXT NOT NULL,
  scope_dir    TEXT NOT NULL,
  created_at   INTEGER NOT NULL,
  created_by   TEXT NOT NULL,
  approval_id  TEXT,
  revoked_at   INTEGER,
  revoked_by   TEXT,
  last_used_at INTEGER,
  use_count    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE turn_journal (
  turn_id TEXT NOT NULL,
  seq INTEGER NOT NULL,
  at INTEGER NOT NULL,
  entry TEXT NOT NULL,                          -- {head} | {message} | {started}, as JSON
  PRIMARY KEY (turn_id, seq)
) WITHOUT ROWID;

CREATE TABLE turn_records (
  id TEXT PRIMARY KEY,
  -- The conversation this belongs to, as `sessions.id` — so a transcript is one indexed lookup and a
  -- deleted conversation takes its turns with it.
  session_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  gateway_id TEXT NOT NULL,
  chat_id TEXT NOT NULL,
  -- The inbound message that started it, so a caller that dispatched one can find its own turn
  -- without guessing from timestamps.
  message_id TEXT,
  sender_id TEXT,

  -- running | done | failed | cancelled | interrupted
  --
  -- `interrupted` is set at boot for rows left `running` by a daemon that died: the turn is not
  -- coming back, and a client polling one would wait forever. Same rule as `jobs`.
  status TEXT NOT NULL,

  -- What was asked, as the model received it — after the address prefix is stripped, before the
  -- overheard-context block is composed in.
  prompt TEXT NOT NULL,
  -- Grows while the turn runs. A partial answer is what makes the dashboard able to stream: the
  -- executor already sees text deltas, and until now it accumulated them where nobody could look.
  reply TEXT NOT NULL DEFAULT '',
  error TEXT,

  model TEXT,
  tool_calls INTEGER NOT NULL DEFAULT 0,
  input_tokens INTEGER,
  output_tokens INTEGER,

  started_at INTEGER NOT NULL,
  ended_at INTEGER
, attachments TEXT, iterations INTEGER, seq INTEGER NOT NULL DEFAULT 0, delivered_at INTEGER, cause TEXT);

CREATE TABLE user_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token TEXT NOT NULL UNIQUE,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,                  -- stored lowercased
  password_hash TEXT NOT NULL,                    -- argon2id
  role TEXT NOT NULL DEFAULT 'viewer',            -- admin | operator | viewer
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
